import type {LinkContent} from '@smart/aem-utils';
import {createLinkProps} from '@smart/aem-utils';
import {Dialog, Link, Text} from '@smart/react-components';
import React from 'react';
import {useAppModelContext} from '../../hooks/use-app-model';
import {useFeatureAppEnv} from '../../hooks/use-feature-app-env';
import {CircleBadge} from '../circle-badge';
import {ColumnDialog} from './column-dialog';
import type {DialogProps} from './types';

export const AccessoriesDialog = ({onOpenChange, open}: DialogProps) => {
  const {
    appModel: {
      accessoriesAndWallboxes: {
        accessoriesModalInfoText: infoText,
        accessoriesModalSelectCarHeadline: primaryHeadline,
        accessoriesModalSelectCarDetails: primaryDetails,
        selectACarCtaLabel: primaryCtaLabel,
        selectACarCtaPath: primaryCtaLink,
        accessoriesModalDealerLocatorHeadline: secondaryHeadline,
        accessoriesModalDealerLocatorDetails: secondaryDetails,
        dealerLocatorCtaLabel: secondaryCtaLabel,
        loginCtaPath: secondaryCtaHref,
      },
    },
  } = useAppModelContext();

  const {
    featureServices: {
      'endpoint-directory': endpointDirectory,
      's2:history': historyService,
    },
  } = useFeatureAppEnv();

  return (
    <ColumnDialog onOpenChange={onOpenChange} open={open} infoText={infoText}>
      <ColumnDialog.Column>
        <CircleBadge variant="primary">1</CircleBadge>
        <Dialog.Text>
          <Text variant="hl-50" as="h2" margin={{y: 200}}>
            {primaryHeadline}
          </Text>
          <Text as="p">{primaryDetails}</Text>
        </Dialog.Text>
        <Dialog.Button
          variant="primary"
          mode={300}
          style={{marginBlockStart: `auto`}}
          width="full"
          asChild
        >
          <Link
            {...createLinkProps({
              historyService,
              content: primaryCtaLink as LinkContent,
              envName: endpointDirectory.envName,
            })}
          >
            {primaryCtaLabel}
          </Link>
        </Dialog.Button>
      </ColumnDialog.Column>
      <ColumnDialog.Column>
        <CircleBadge variant="secondary">2</CircleBadge>
        <Dialog.Text>
          <Text variant="hl-50" as="h2" margin={{y: 200}}>
            {secondaryHeadline}
          </Text>
          <Text as="p">{secondaryDetails}</Text>
        </Dialog.Text>
        <Dialog.Button
          variant="secondary"
          asChild
          mode={300}
          style={{marginBlockStart: `auto`}}
          width="full"
        >
          <Link href={secondaryCtaHref}>{secondaryCtaLabel}</Link>
        </Dialog.Button>
      </ColumnDialog.Column>
    </ColumnDialog>
  );
};

import {createLinkProps} from '@smart/aem-utils';
import type {LinkContent} from '@smart/aem-utils';
import {useFeatureAppEnv} from '@smart/feature-app';
import {Dialog, Link, Text} from '@smart/react-components';
import React from 'react';
import {useAppModelContext} from '../../hooks/use-app-model';
import {CircleBadge} from '../circle-badge';
import {ColumnDialog} from './column-dialog';
import type {DialogProps} from './types';

export const ExtendedWarrantyNotCompatibleDialog = ({
  onOpenChange,
  open,
}: DialogProps) => {
  const {
    appModel: {
      extendedWarrantyAemData: {
        title: infoText,
        leftHeadline: primaryHeadline,
        leftDescription: primaryDetails,
        leftButtonLabel: primaryCtaLabel,
        leftButtonPath: primaryCtaHref,
        rightHeadline: secondaryHeadline,
        rightDescription: secondaryDetails,
        rightButtonLabel: secondaryCtaLabel,
        rightButtonPath: secondaryCtaHref,
      },
    },
  } = useAppModelContext();

  const isSmartStoreLink =
    primaryCtaHref &&
    (primaryCtaHref as {pathname: string}).pathname.includes(`products/`);
  const {
    featureServices: {
      'endpoint-directory': endpointDirectory,
      's2:history': historyService,
    },
  } = useFeatureAppEnv();
  return (
    <ColumnDialog onOpenChange={onOpenChange} open={open} infoText={infoText}>
      <ColumnDialog.Column>
        <CircleBadge variant="primary">1</CircleBadge>
        <Dialog.Text>
          <Text variant="hl-50" as="h2" margin={{y: 200}}>
            {primaryHeadline}
          </Text>
          <Text as="p">{primaryDetails}</Text>
        </Dialog.Text>
        {isSmartStoreLink ? (
          <Dialog.Button
            variant="primary"
            onClick={() => onOpenChange(false)}
            mode={300}
            style={{marginBlockStart: `auto`}}
            width="full"
          >
            {primaryCtaLabel}
          </Dialog.Button>
        ) : (
          <Dialog.Button
            variant="primary"
            asChild
            mode={300}
            style={{marginBlockStart: `auto`}}
            width="full"
          >
            <Link
              {...createLinkProps({
                historyService,
                content: primaryCtaHref as LinkContent,
                envName: endpointDirectory.envName,
              })}
            >
              {primaryCtaLabel}
            </Link>
          </Dialog.Button>
        )}
      </ColumnDialog.Column>
      <ColumnDialog.Column>
        <CircleBadge variant="secondary">2</CircleBadge>
        <Dialog.Text>
          <Text variant="hl-50" as="h2" margin={{y: 200}}>
            {secondaryHeadline}
          </Text>
          <Text as="p">{secondaryDetails}</Text>
        </Dialog.Text>
        <Dialog.Button
          variant="secondary"
          asChild
          mode={300}
          style={{marginBlockStart: `auto`}}
          width="full"
        >
          <Link href={secondaryCtaHref}>{secondaryCtaLabel}</Link>
        </Dialog.Button>
      </ColumnDialog.Column>
    </ColumnDialog>
  );
};

