import {Button, Link} from '@smart/react-components';
import {Heading} from '@smart/web-components';
import * as React from 'react';
import {useAppModelContext} from '../../hooks/use-app-model';
import styles from './index.module.scss';

const baseClass = `empty`;

export const EmptyState = (): JSX.Element => {
  const {appModel} = useAppModelContext();

  return (
    <div className={styles[baseClass]}>
      <Heading variant={`headline-functional-400`}>
        {appModel.emptyStateBodyText}
      </Heading>
      <Button asChild mode={300} variant="secondary">
        <Link href={appModel.emptyStateButtonPath}>
          {appModel.emptyStateButtonLabel}
        </Link>
      </Button>
    </div>
  );
};
